'use client'
import dynamic from 'next/dynamic';

const CalendarHeatmap = dynamic(
  () => import('react-calendar-heatmap').then(mod => mod.default),
  { ssr: false }
);

// Import styles
import 'react-calendar-heatmap/dist/styles.css';

export function UserHeatmap({ submissions }: { submissions: any[] }) {
    // Process submissions into values
    const data = new Map<string, number>();

    submissions.forEach(sub => {
        const date = new Date(sub.creationTimeSeconds * 1000).toISOString().split('T')[0];
        data.set(date, (data.get(date) || 0) + 1);
    });

    const values = Array.from(data.entries()).map(([date, count]) => ({ date, count }));

    // Get last 365 days
    const today = new Date();
    const yearAgo = new Date();
    yearAgo.setFullYear(today.getFullYear() - 1);

    return (
        <div className="w-full h-full">
            <CalendarHeatmap
                startDate={yearAgo}
                endDate={today}
                values={values}
                classForValue={(value) => {
                    if (!value) return 'color-empty';
                    return `color-github-${Math.min(4, value.count)}`;
                }}
                tooltipDataAttrs={(value: any) => ({
                    'data-tip': value && value.date ? `${value.date}: ${value.count} submissions` : 'No submissions',
                })}
                showWeekdayLabels
            />
            <style jsx global>{`
        .react-calendar-heatmap text {
          font-size: 10px;
          fill: #71717a;
        }
        .react-calendar-heatmap .color-empty { fill: #18181b; } /* zinc-900 */
        .react-calendar-heatmap .color-github-1 { fill: #0e4429; }
        .react-calendar-heatmap .color-github-2 { fill: #006d32; }
        .react-calendar-heatmap .color-github-3 { fill: #26a641; }
        .react-calendar-heatmap .color-github-4 { fill: #39d353; }
      `}</style>
        </div>
    );
}
