'use client';
import { useState, useEffect } from 'react';
import { Plus, Trash2, TrendingUp, Activity, Users, Clock, ExternalLink } from 'lucide-react';
import { addPinnedRival, getRivals, getRivalActivity, getRivalHistory } from '@/app/actions';
import { cn } from '@/lib/utils';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

export function RivalryWidget() {
    const [rivals, setRivals] = useState<any[]>([]);
    const [newHandle, setNewHandle] = useState('');
    const [loading, setLoading] = useState(true);
    const [tab, setTab] = useState<'list' | 'activity' | 'graph'>('list');

    const [activity, setActivity] = useState<any[]>([]);
    const [graphData, setGraphData] = useState<any[]>([]);
    const [loadingStats, setLoadingStats] = useState(false);

    const fetchRivals = async () => {
        const handle = localStorage.getItem('cp-handle');
        if (handle) {
            const data = await getRivals(handle);
            setRivals(data);
            return data;
        }
        setLoading(false);
        return [];
    };

    useEffect(() => {
        fetchRivals().then((data) => {
            if (data.length > 0) loadStats(data.map((r: any) => r.rivalHandle));
            setLoading(false);
        });
    }, []);

    const loadStats = async (handles: string[]) => {
        setLoadingStats(true);
        const myHandle = localStorage.getItem('cp-handle');
        const allHandles = myHandle ? [myHandle, ...handles] : handles;

        // 1. Fetch Activity (Live Feed)
        const recentSubs = await getRivalActivity(handles); // only friends
        setActivity(recentSubs);

        // 2. Fetch Graph Data
        const historyData = await getRivalHistory(allHandles); // friends + me
        // Normalize for graph
        // This is complex because timestamps differ. We'll simplify: just plot last 10 contests for everyone?
        // Or better: time-based.
        // For MVP, lets just take the last 10 ratings of everyone and plot index-based for comparison "Recent Trajectory"

        const maxLength = Math.max(...historyData.map(h => h.history.length));
        const chartData = [];
        for (let i = 0; i < 20; i++) { // show last 20 contests
            const point: any = { i };
            historyData.forEach(h => {
                const len = h.history.length;
                const idx = len - 20 + i;
                if (idx >= 0) point[h.handle] = h.history[idx].newRating;
            });
            chartData.push(point);
        }
        setGraphData(chartData);

        setLoadingStats(false);
    };

    const handleAdd = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newHandle.trim()) return;

        const handle = localStorage.getItem('cp-handle');
        if (handle) {
            await addPinnedRival(handle, newHandle);
            setNewHandle('');
            const updated = await fetchRivals();
            loadStats(updated.map((r: any) => r.rivalHandle));
        }
    };

    return (
        <div className="bg-zinc-900/50 p-6 rounded-xl border border-zinc-800 h-full flex flex-col min-h-[400px]">
            <div className="flex items-center justify-between mb-4">
                <h3 className="text-zinc-400 font-medium flex items-center gap-2">
                    <TrendingUp className="text-red-500" size={18} /> Rivalry Tracker
                </h3>
                <div className="flex bg-zinc-950 rounded-lg p-1 border border-zinc-800">
                    <button onClick={() => setTab('list')} className={cn("px-3 py-1 text-xs rounded-md transition", tab === 'list' ? "bg-zinc-800 text-white shadow" : "text-zinc-500 hover:text-zinc-300")}>
                        <Users size={14} />
                    </button>
                    <button onClick={() => setTab('activity')} className={cn("px-3 py-1 text-xs rounded-md transition", tab === 'activity' ? "bg-zinc-800 text-white shadow" : "text-zinc-500 hover:text-zinc-300")}>
                        <Activity size={14} />
                    </button>
                    <button onClick={() => setTab('graph')} className={cn("px-3 py-1 text-xs rounded-md transition", tab === 'graph' ? "bg-zinc-800 text-white shadow" : "text-zinc-500 hover:text-zinc-300")}>
                        <TrendingUp size={14} />
                    </button>
                </div>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto min-h-0 relative">
                {loading ? (
                    <div className="absolute inset-0 flex items-center justify-center text-zinc-600 text-xs">Loading...</div>
                ) : (
                    <>
                        {/* LIST TAB */}
                        {tab === 'list' && (
                            <div className="space-y-4">
                                {rivals.length === 0 ? (
                                    <div className="text-zinc-600 text-xs italic text-center py-8">
                                        Pin a rival to stalk their progress.
                                    </div>
                                ) : (
                                    <div className="space-y-3">
                                        {rivals.map((r) => (
                                            <div key={r.handle} className="flex items-center justify-between bg-zinc-950 p-3 rounded-lg border border-zinc-900 group">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-8 h-8 rounded-full overflow-hidden bg-zinc-800">
                                                        <img src={r.titlePhoto || 'https://userpic.codeforces.org/no-title.jpg'} alt="" className="w-full h-full object-cover" />
                                                    </div>
                                                    <div>
                                                        <div className="font-bold text-sm text-zinc-200">{r.rivalHandle}</div>
                                                        <div className={cn("text-xs font-mono", getRatingColor(r.rating || 0))}>
                                                            {r.rating || 'Unrated'}
                                                        </div>
                                                    </div>
                                                </div>
                                                <a href={`https://codeforces.com/profile/${r.rivalHandle}`} target="_blank" className="text-zinc-600 hover:text-white transition opacity-0 group-hover:opacity-100">
                                                    <ExternalLink size={14} />
                                                </a>
                                            </div>
                                        ))}
                                    </div>
                                )}
                                <form onSubmit={handleAdd} className="mt-4 flex gap-2">
                                    <input
                                        value={newHandle}
                                        onChange={(e) => setNewHandle(e.target.value)}
                                        placeholder="Add handle..."
                                        className="flex-1 bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-xs text-white focus:outline-none focus:ring-1 focus:ring-red-500"
                                    />
                                    <button type="submit" className="bg-zinc-800 hover:bg-zinc-700 text-white p-2 rounded-lg transition">
                                        <Plus size={16} />
                                    </button>
                                </form>
                            </div>
                        )}

                        {/* ACTIVITY TAB */}
                        {tab === 'activity' && (
                            <div className="space-y-3">
                                {activity.length === 0 ? (
                                    <div className="text-center py-8 text-zinc-600 text-xs">No recent activity detected.</div>
                                ) : (
                                    activity.map((sub: any, i) => (
                                        <div key={i} className="bg-zinc-950 p-3 rounded-lg border border-zinc-900 text-xs">
                                            <div className="flex justify-between mb-1">
                                                <span className="font-bold text-zinc-300">{sub.handle}</span>
                                                <span className="text-zinc-600 flex items-center gap-1">
                                                    <Clock size={10} /> {Math.floor((Date.now() / 1000 - sub.creationTimeSeconds) / 3600)}h ago
                                                </span>
                                            </div>
                                            <div className="flex justify-between items-center">
                                                <a href={`https://codeforces.com/problemset/problem/${sub.problem.contestId}/${sub.problem.index}`} target="_blank" className="text-blue-400 hover:underline truncate max-w-[150px]">
                                                    {sub.problem.index}. {sub.problem.name}
                                                </a>
                                                <span className={`px-1.5 py-0.5 rounded ${sub.verdict === 'OK' ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                                                    {sub.verdict === 'OK' ? 'AC' : 'WA'}
                                                </span>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        )}

                        {/* GRAPH TAB */}
                        {tab === 'graph' && (
                            <div className="h-[250px] w-full text-xs">
                                <ResponsiveContainer width="100%" height="100%">
                                    <LineChart data={graphData}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                                        <XAxis dataKey="i" hide />
                                        <YAxis domain={['auto', 'auto']} stroke="#666" fontSize={10} width={30} />
                                        <Tooltip
                                            contentStyle={{ backgroundColor: '#18181b', border: '1px solid #27272a' }}
                                            itemStyle={{ fontSize: '12px' }}
                                        />
                                        {/* Dynamically render lines for each rival + me */}
                                        {rivals.map((r, i) => (
                                            <Line
                                                key={r.rivalHandle}
                                                type="monotone"
                                                dataKey={r.rivalHandle}
                                                stroke={['#ef4444', '#3b82f6', '#10b981', '#f59e0b'][i % 4]}
                                                dot={false}
                                                strokeWidth={2}
                                            />
                                        ))}
                                        <Line type="monotone" dataKey={localStorage.getItem('cp-handle') || ''} stroke="#fff" strokeWidth={2} dot={{ r: 2 }} />
                                    </LineChart>
                                </ResponsiveContainer>
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
    );
}

function getRatingColor(rating: number) {
    if (!rating) return "text-zinc-500";
    if (rating < 1200) return "text-gray-400";
    if (rating < 1400) return "text-green-400";
    if (rating < 1600) return "text-cyan-400";
    if (rating < 1900) return "text-blue-500";
    if (rating < 2100) return "text-purple-400";
    if (rating < 2400) return "text-orange-400";
    return "text-red-500";
}
